package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** A physical return parcel owns one THK; refund source ledgers remain independent. */
@Service public class RefundParcels {
    @Resource WmsStore db;
    @Resource WmsConnections connections;
    @Resource QimenReturnProtocol protocol;
    @Resource WmsInteractionLog logs;
    @Resource SharedRefundDocuments shared;
    @Resource RefundReceiptAllocator allocator;

    private long n(Object value){return value==null?0:id(value);}
    @SuppressWarnings("unchecked") private Map<String,Object> object(Object raw){if(raw==null)return Collections.emptyMap();if(raw instanceof Map)return (Map<String,Object>)raw;try{return db.json.readValue(text(raw),Map.class);}catch(Exception e){throw new IllegalArgumentException("合包配置快照无法读取");}}
    private Map<String,Object> parcel(String c,long id,boolean lock){return db.one("SELECT * FROM wms_refund_parcel WHERE company_code=? AND id=?"+(lock?" FOR UPDATE":""),c,id);}
    private List<Map<String,Object>> members(String c,long id){return db.jdbc.queryForList("SELECT m.*,t.return_sn,t.dispatch_state,t.attempts,t.cancel_state,t.receipt_state,t.accepted_quantity,t.posted_quantity,t.external_order,t.control_version document_version FROM wms_refund_parcel_member m LEFT JOIN wms_refund_return t ON t.company_code=m.company_code AND t.id=m.task_id WHERE m.company_code=? AND m.parcel_id=? AND m.active=1 ORDER BY m.id LIMIT 101",c,id);}
    private void notifyPlans(String c,long parcel){db.jdbc.update("UPDATE wms_refund_return t JOIN wms_refund_parcel_member m ON m.company_code=t.company_code AND m.task_id=t.id SET t.progress_revision=t.progress_revision+1,t.notify_pending=1 WHERE m.company_code=? AND m.parcel_id=?",c,parcel);}
    public List<Map<String,Object>> list(String c,long refund){
        List<Map<String,Object>> rows=db.jdbc.queryForList("SELECT DISTINCT p.* FROM wms_refund_parcel p JOIN wms_refund_parcel_member m ON m.company_code=p.company_code AND m.parcel_id=p.id WHERE m.company_code=? AND m.refund_id=? ORDER BY p.id DESC LIMIT 50",c,refund);if(rows.isEmpty())return rows;
        return fill(c,rows);
    }
    public Map<String,Object> inspect(String c,long parcel,long channel,String tid){Map<String,Object> p=parcel(c,parcel,false);List<Map<String,Object>> ms=members(c,parcel);require(!ms.isEmpty()&&ms.stream().allMatch(m->n(m.get("channel_id"))==channel&&text(m.get("platform_tid")).equals(tid)),"目标包裹与当前店铺或原平台订单不一致");Map<String,Object> result=fill(c,new ArrayList<>(Collections.singletonList(p))).get(0);Map<String,Object> connection=connections.get(c,id(p.get("connection_id")));result.put("late_append_supported",false);return result;}
    private List<Map<String,Object>> fill(String c,List<Map<String,Object>> rows){
        List<Object> args=new ArrayList<>();args.add(c);for(Map<String,Object> p:rows){args.add(p.get("id"));p.put("members",new ArrayList<>());p.put("receipts",new ArrayList<>());}String in=String.join(",",Collections.nCopies(rows.size(),"?"));Map<Long,Map<String,Object>> byId=new HashMap<>();for(Map<String,Object> p:rows)byId.put(id(p.get("id")),p);
        List<Map<String,Object>> ms=db.jdbc.queryForList("SELECT m.*,t.return_sn,t.dispatch_state,t.attempts,t.cancel_state,t.receipt_state,t.accepted_quantity,t.posted_quantity,t.external_order,t.control_version document_version FROM wms_refund_parcel_member m LEFT JOIN wms_refund_return t ON t.company_code=m.company_code AND t.id=m.task_id WHERE m.company_code=? AND m.parcel_id IN ("+in+") ORDER BY m.id LIMIT 5001",args.toArray());
        require(ms.size()<=5000,"关联安排过多，请缩小退款范围");for(Map<String,Object> m:ms){m.remove("request_json");add(byId.get(id(m.get("parcel_id"))),"members",m);}
        List<Map<String,Object>> es=db.jdbc.queryForList("SELECT id,parcel_id,document_id,message_id,mode,quantity,state,actor,reason,evidence,create_time,allocation_metadata,IF(state='WAIT_ALLOCATION',payload,NULL) payload,allocation_json FROM wms_refund_parcel_receipt WHERE company_code=? AND parcel_id IN ("+in+") ORDER BY (state='WAIT_ALLOCATION') DESC,id DESC LIMIT 501",args.toArray());
        for(Map<String,Object> e:es)add(byId.get(id(e.get("parcel_id"))),"receipts",e);for(Map<String,Object> p:rows){p.put("receipt_limit_reached",es.size()>500);List<Map<String,Object>> docs=db.jdbc.queryForList("SELECT id,return_sn,ticket_id,quantity,dispatch_state,external_order,warehouse_status,cancel_state,control_version,last_error FROM wms_refund_parcel_document WHERE company_code=? AND parcel_id=? ORDER BY generation DESC LIMIT 1",c,p.get("id"));p.put("warehouse_document",docs.isEmpty()?null:docs.get(0));if(!docs.isEmpty()){List<Map<String,Object>> sourceDocs=db.jdbc.queryForList("SELECT g.source_line_id,d.return_sn,d.dispatch_state,d.cancel_state FROM wms_refund_parcel_document d JOIN wms_tickets_goods g ON UPPER(g.company_code)=d.company_code AND g.sn=d.return_sn WHERE d.company_code=? AND d.parcel_id=?",c,p.get("id"));for(Map<String,Object> member:(List<Map<String,Object>>)p.get("members")){Map<String,Object> own=sourceDocs.stream().filter(x->n(x.get("source_line_id"))==n(member.get("task_id"))).findFirst().orElse(docs.get(0));member.put("return_sn",own.get("return_sn"));member.put("dispatch_state",own.get("dispatch_state"));member.put("cancel_state",own.get("cancel_state"));}}}return rows;
    }
    @SuppressWarnings("unchecked") private void add(Map<String,Object> p,String key,Map<String,Object> row){((List<Map<String,Object>>)p.get(key)).add(row);}
    public List<Map<String,Object>> capabilities(String c){return db.jdbc.queryForList("SELECT v.wms_simulation_code store_code,v.wms_simulation_name store_name,c.name connection_name,c.shared_return_waybill,c.shared_return_append,c.shared_return_late_append,IF(c.enabled=1 AND c.provider='QIMEN' AND c.api_version='2.0' AND v.status=2 AND r.status=2 AND o.is_enable=2 AND w.status=2 AND v.external_owner<>'' AND v.external_warehouse<>'',1,0) usable FROM wms_simulation_store_info v JOIN owner_warehouse r ON UPPER(r.company_code)=UPPER(v.company_code) AND r.id=v.owner_warehouse_id JOIN owner_info o ON UPPER(o.company_code)=UPPER(r.company_code) AND o.id=r.owner_id JOIN wms_real_store_info w ON UPPER(w.company_code)=UPPER(r.company_code) AND w.id=r.real_store_id LEFT JOIN wms_connection c ON UPPER(c.company_code)=UPPER(v.company_code) AND c.id=v.connection_id WHERE UPPER(v.company_code)=? ORDER BY v.id LIMIT 1000",c);}
    public List<Map<String,Object>> candidates(String c,String carrier,String waybill){require(carrier.length()<=64&&waybill.length()<=128,"快递或运单号过长");return db.jdbc.queryForList("SELECT p.id,p.parcel_sn,p.carrier_code,p.waybill,p.store_code,p.owner_code,p.real_store_code,COUNT(m.id) member_count,COUNT(DISTINCT m.refund_id) refund_count,MIN(m.channel_id) channel_id,MIN(m.platform_tid) platform_tid,MAX(IF(t.attempts>0,1,0)) dispatched,(SELECT COUNT(*) FROM wms_refund_parcel_receipt e WHERE e.company_code=p.company_code AND e.parcel_id=p.id) receipt_count FROM wms_refund_parcel p LEFT JOIN wms_refund_parcel_member m ON m.company_code=p.company_code AND m.parcel_id=p.id LEFT JOIN wms_refund_return t ON t.company_code=m.company_code AND t.id=m.task_id WHERE p.company_code=? AND p.carrier_code=? AND p.waybill=? GROUP BY p.id LIMIT 20",c,carrier,waybill);}
    public Map<String,Object> attach(String c,long plan,Map<String,Object> input){
        Map<String,Object> policy=object(input.get("policy"));boolean auto="AUTO".equals(text(input.get("association_mode")));require(!policy.isEmpty(),"缺少可信合包规则");require(!Boolean.TRUE.equals(input.get("late_review")),"共同THK不支持实收后扩大计划；请核对仓库差异，不得补建独立THK");require(n(policy.get("enabled"))==1&&n(policy.get(auto?"auto_enabled":"manual_enabled"))==1,"店铺未允许本次合包方式");require(n(input.get("channel_id"))>0&&!text(input.get("platform_tid")).isEmpty(),"店铺或平台订单身份缺失");
        Map<String,Object> command=object(input.get("request_json"));require(n(command.get("quantity"))==n(input.get("quantity"))&&n(command.get("refund_id"))==n(input.get("refund_id"))&&text(command.get("sku_sn")).equals(text(input.get("sku_sn"))),"缺少可信退回来源快照");
        String carrier=required(input,"carrier_code",50).toUpperCase(Locale.ROOT),waybill=required(input,"waybill",50),store=required(input,"store_code",64),address=required(input,"return_address",500),contact=required(input,"return_contact",200);require(carrier.matches("[A-Z0-9_-]{1,50}")&&waybill.matches("[A-Za-z0-9_-]{1,50}")&&Boolean.TRUE.equals(input.get("confirmed")),"请核实承运商、运单及同一实际包裹");
        Map<String,Object> w=db.one("SELECT v.connection_id,v.external_owner,v.external_warehouse,o.owner_code,w.real_store_code FROM wms_simulation_store_info v JOIN owner_warehouse r ON UPPER(r.company_code)=UPPER(v.company_code) AND r.id=v.owner_warehouse_id JOIN owner_info o ON UPPER(o.company_code)=UPPER(r.company_code) AND o.id=r.owner_id JOIN wms_real_store_info w ON UPPER(w.company_code)=UPPER(r.company_code) AND w.id=r.real_store_id WHERE UPPER(v.company_code)=? AND v.wms_simulation_code=?",c,store);connections.usable(c,id(w.get("connection_id")));require(!text(w.get("external_owner")).isEmpty()&&!text(w.get("external_warehouse")).isEmpty(),"接收仓或货主映射缺失");if(auto)require(((List<?>)policy.getOrDefault("store_codes",Collections.emptyList())).contains(store),"当前退回仓未纳入配置");
        return db.tx().execute(tx->{String sn="RPK"+UUID.randomUUID().toString().replace("-","");long seconds=n(policy.get("collect_seconds"));db.jdbc.update("INSERT IGNORE INTO wms_refund_parcel(company_code,parcel_sn,carrier_code,waybill,store_code,connection_id,external_owner,external_warehouse,owner_code,real_store_code,actor,reason,evidence,return_address,return_contact,dispatch_after) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,DATE_ADD(NOW(),INTERVAL ? SECOND))",c,sn,carrier,waybill,store,w.get("connection_id"),w.get("external_owner"),w.get("external_warehouse"),w.get("owner_code"),w.get("real_store_code"),required(input,"actor",64),required(input,"reason",500),required(input,"evidence",1000),address,contact,seconds);
            Map<String,Object> p=db.one("SELECT * FROM wms_refund_parcel WHERE company_code=? AND carrier_code=? AND waybill=? FOR UPDATE",c,carrier,waybill);long parcel=id(p.get("id"));require(store.equals(text(p.get("store_code")))&&address.equals(text(p.get("return_address")))&&contact.equals(text(p.get("return_contact")))&&id(w.get("connection_id"))==id(p.get("connection_id"))&&text(w.get("external_owner")).equals(text(p.get("external_owner")))&&text(w.get("external_warehouse")).equals(text(p.get("external_warehouse"))),"接收仓、货主、退回地址或联系信息不同，不能合包");
            List<Map<String,Object>> old=db.jdbc.queryForList("SELECT * FROM wms_refund_parcel_member WHERE company_code=? AND plan_id=? AND active=1 FOR UPDATE",c,plan);if(!old.isEmpty()){require(id(old.get(0).get("parcel_id"))==parcel,"计划已关联其他包裹");return p;}
            require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_document WHERE company_code=? AND parcel_id=?",Long.class,c,parcel)==0,"共同THK已冻结范围；不能静默追加，请核对仓库改单或取消重建");require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_return WHERE company_code=? AND plan_id=?",Long.class,c,plan)==0,"当前计划已有仓库安排，不能覆盖");
            List<Map<String,Object>> ms=members(c,parcel);if(!ms.isEmpty()){require(n(input.get("join_parcel_id"))==parcel,"请明确加入已有包裹");require(ms.stream().allMatch(m->n(m.get("channel_id"))==n(input.get("channel_id"))),"不能跨店铺合包");boolean same=ms.stream().allMatch(m->text(m.get("platform_tid")).equals(text(input.get("platform_tid"))));require(same||(!auto&&"CROSS_ORDER_MANUAL".equals(text(policy.get("scope")))&&Boolean.TRUE.equals(input.get("buyer_verified"))),"跨订单须配置允许并核实同一买家");}
            long refunds=ms.stream().map(m->id(m.get("refund_id"))).distinct().count()+(ms.stream().anyMatch(m->id(m.get("refund_id"))==n(input.get("refund_id")))?0:1),qty=n(input.get("quantity"));require(qty>0&&qty<=100000000&&ms.size()<100&&refunds<=n(policy.get("max_refunds")),"合包数量或退款数超过上限");long total=qty+ms.stream().mapToLong(m->id(m.get("quantity"))).sum();require(n(policy.get("max_quantity"))==0||total<=n(policy.get("max_quantity")),"超过单包最大件数");
            db.insert("wms_refund_parcel_member",map("company_code",c,"parcel_id",parcel,"plan_id",plan,"generation",1,"refund_id",input.get("refund_id"),"refund_sn",required(input,"refund_sn",64),"order_sn",required(input,"order_sn",64),"source_line_id",input.get("source_line_id"),"sku_sn",input.get("sku_sn"),"quantity",qty,"actor",input.get("actor"),"reason",input.get("reason"),"evidence",input.get("evidence"),"channel_id",input.get("channel_id"),"platform_tid",input.get("platform_tid"),"association_mode",auto?"AUTO":"MANUAL","policy_json",db.encode(policy),"request_json",db.encode(command)));
            db.jdbc.update("UPDATE wms_refund_parcel SET control_version=control_version+1,dispatch_after=DATE_ADD(NOW(),INTERVAL ? SECOND) WHERE company_code=? AND id=?",seconds,c,parcel);return parcel(c,parcel,false);
        });
    }
    public void detach(String c,long refund,long plan){db.tx().execute(tx->{List<Map<String,Object>> ms=db.jdbc.queryForList("SELECT * FROM wms_refund_parcel_member WHERE company_code=? AND refund_id=? AND plan_id=? AND active=1",c,refund,plan);if(ms.isEmpty())return null;long parcel=id(ms.get(0).get("parcel_id"));parcel(c,parcel,true);require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_document WHERE company_code=? AND parcel_id=?",Long.class,c,parcel)==0,"共同THK已冻结，请到包裹核对全部退款并整单截停");db.jdbc.update("DELETE FROM wms_refund_parcel_member WHERE company_code=? AND refund_id=? AND plan_id=? AND active=1",c,refund,plan);db.jdbc.update("UPDATE wms_refund_parcel SET control_version=control_version+1 WHERE company_code=? AND id=?",c,parcel);return null;});}
    public Map<String,Object> transport(String c,long refund,long parcel,Map<String,Object> input){return db.tx().execute(tx->{Map<String,Object> p=authorize(c,refund,parcel,true);require(id(p.get("control_version"))==id(input.get("control_version")),"包裹信息已变化，请刷新");String state=required(input,"transport_state",24);require(Arrays.asList("WAITING","IN_TRANSIT","DELIVERED","EXCEPTION").contains(state),"物流状态无效");db.jdbc.update("UPDATE wms_refund_parcel SET transport_state=?,control_version=control_version+1,actor=?,reason=?,evidence=? WHERE company_code=? AND id=?",state,required(input,"actor",64),required(input,"reason",500),required(input,"evidence",1000),c,parcel);return parcel(c,parcel,false);});}
    Map<String,Object> authorize(String c,long refund,long parcel,boolean lock){Map<String,Object> p=parcel(c,parcel,lock);require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_member WHERE company_code=? AND parcel_id=? AND refund_id=?",Long.class,c,parcel,refund)>0,"包裹不属于当前退款单");return p;}
    /** Shared message registry prevents the same warehouse event being posted once per TK. */
    void direct(String c,Map<String,Object> task,WmsProtocol.Receipt receipt,long log,Runnable accept){
        List<Long> ids=db.jdbc.queryForList("SELECT parcel_id FROM wms_refund_parcel_member WHERE company_code=? AND task_id=?",Long.class,c,task.get("id"));if(ids.isEmpty()){accept.run();return;}
        db.tx().execute(tx->{long parcel=ids.get(0);parcel(c,parcel,true);String digest=QimenProtocol.hash("SHA-256",db.encode(receipt));
            List<Map<String,Object>> old=db.jdbc.queryForList("SELECT * FROM wms_refund_parcel_receipt WHERE company_code=? AND parcel_id=? AND message_id=? FOR UPDATE",c,parcel,receipt.messageId);
            if(!old.isEmpty()){Map<String,Object> e=old.get(0);require("DIRECT".equals(e.get("mode"))&&id(e.get("task_id"))==id(task.get("id"))&&digest.equals(e.get("payload_hash")),"该包裹消息已用于其他单据或合包回传，不能重复入账");return null;}
            accept.run();db.insert("wms_refund_parcel_receipt",map("company_code",c,"parcel_id",parcel,"message_id",receipt.messageId,"mode","DIRECT","task_id",task.get("id"),"payload_hash",digest,"payload",db.encode(receipt),"quantity",quantity(receipt),"state","DOCUMENT","source_log_id",log));db.jdbc.update("UPDATE wms_refund_parcel SET control_version=control_version+1 WHERE company_code=? AND id=?",c,parcel);return null;
        });
    }
    private long quantity(WmsProtocol.Receipt r){long n=0;for(WmsProtocol.Line l:r.lines){require(l.good>=0&&l.bad>=0,"实收数量无效");n=Math.addExact(n,(long)l.good+l.bad);}return n;}
    public String callback(String c,String key,Map<String,String> params,String body){return callback(c,key,params,body,null);}
    public String callback(String c,String key,Map<String,String> params,String body,RefundReturnService returns){
        Map<String,Object> connection=db.one("SELECT * FROM wms_connection WHERE company_code=? AND callback_key=?",c,key);long log=logs.start(c,id(connection.get("id")),null,"","IN","REFUND_RETURN_RECEIPT",body),start=System.currentTimeMillis();QimenProtocol ack=new QimenProtocol();
        try{WmsProtocol.Receipt r=protocol.callback(connection,connections.secret(connection),params,body);db.tx().execute(tx->{require(r.ticketSn.startsWith("THK"),"仓库回传必须提供已下发THK，RPK仅为OMS包裹号");Map<String,Object> doc=db.one("SELECT * FROM wms_refund_parcel_document WHERE company_code=? AND return_sn=?",c,r.ticketSn);Map<String,Object> p=db.one("SELECT * FROM wms_refund_parcel WHERE company_code=? AND id=? FOR UPDATE",c,doc.get("parcel_id"));long parcel=id(p.get("id"));db.one("SELECT id FROM wms_refund_parcel_document WHERE company_code=? AND id=? FOR UPDATE",c,doc.get("id"));require(id(p.get("connection_id"))==id(connection.get("id"))&&text(p.get("external_warehouse")).equals(r.warehouse)&&text(p.get("external_owner")).equals(r.owner),"共同THK仓库或货主不一致");require(!r.externalOrder.isEmpty()&&r.externalOrder.equals(text(doc.get("external_order"))),"仓库单号与原受理不一致");require(Arrays.asList("ACCEPTED","CANCELED").contains(text(doc.get("dispatch_state"))),"共同THK尚未明确受理");db.jdbc.update("UPDATE wms_interaction_log SET ticket_sn=? WHERE id=?",r.ticketSn,log);
            String digest=QimenProtocol.hash("SHA-256",db.encode(r));List<Map<String,Object>> old=db.jdbc.queryForList("SELECT * FROM wms_refund_parcel_receipt WHERE company_code=? AND parcel_id=? AND message_id=? FOR UPDATE",c,parcel,r.messageId);
            if(!old.isEmpty()){require("THK".equals(old.get(0).get("mode"))&&digest.equals(old.get(0).get("payload_hash")),"同一包裹消息内容或归属冲突，不能重复接收");return null;}
            require(!r.messageId.isEmpty()&&r.messageId.length()<=128&&quantity(r)>0,"包裹消息标识或实收数量无效");
            db.insert("wms_refund_parcel_receipt",map("company_code",c,"parcel_id",parcel,"message_id",r.messageId,"mode","THK","document_id",doc.get("id"),"payload_hash",digest,"payload",db.encode(r),"quantity",quantity(r),"state","WAIT_ALLOCATION","source_log_id",log));db.jdbc.update("UPDATE wms_refund_parcel SET control_version=control_version+1 WHERE company_code=? AND id=?",c,parcel);notifyPlans(c,parcel);db.jdbc.update("UPDATE wms_refund_parcel_document SET warehouse_status=?,control_version=control_version+1 WHERE company_code=? AND id=?",r.status,c,doc.get("id"));db.jdbc.update("UPDATE wms_interaction_log SET ticket_sn=? WHERE id=?",r.ticketSn,log);return null;});
            if(returns!=null)autoAllocate(c,log,returns);
            Map<String,Object> event=db.one("SELECT e.state FROM wms_refund_parcel_receipt e JOIN wms_refund_parcel p ON p.company_code=e.company_code AND p.id=e.parcel_id JOIN wms_refund_parcel_document d ON d.company_code=e.company_code AND d.id=e.document_id WHERE e.company_code=? AND d.return_sn=? AND e.message_id=?",c,r.ticketSn,r.messageId);boolean assigned="ALLOCATED".equals(event.get("state"));
            String description=assigned?"共同THK实收已分配；各退款按来源入账":"共同THK实收待核对退款来源；未分配部分未入账";
            String reply=ack.acknowledgement(true,description);logs.finish(log,"SUCCESS",reply,"",System.currentTimeMillis()-start);logs.describe(log,description);return reply;
        }catch(Exception e){String why=e instanceof IllegalArgumentException?text(e.getMessage()):"包裹实收保存未完成，请重试";String reply=ack.acknowledgement(false,why);logs.finish(log,"FAILED",reply,why,System.currentTimeMillis()-start);return reply;}
    }
    void autoAllocate(String c,long log,RefundReturnService returns){
        for(Long event:db.jdbc.queryForList("SELECT id FROM wms_refund_parcel_receipt WHERE company_code=? AND source_log_id=? AND state='WAIT_ALLOCATION'",Long.class,c,log))allocator.attempt(c,event,this,returns);
    }
    public void reconcileAutomatic(String c,RefundReturnService returns){allocator.reconcile(c,this,returns);}
    public Map<String,Object> evaluateAutomatic(String c,long refund,long parcel,long event,Map<String,Object> input,RefundReturnService returns){return allocator.evaluate(c,refund,parcel,event,input,this,returns);}
    public void allocate(String c,long refund,long parcel,long event,Map<String,Object> input,RefundReturnService returns){applyAllocation(c,refund,parcel,event,input,map("method","MANUAL","status","APPLIED","reason",input.get("reason")),returns);}
    void allocateAutomatic(String c,long refund,long parcel,long event,Map<String,Object> input,Map<String,Object> metadata,RefundReturnService returns){Map<String,Object> applied=new LinkedHashMap<>(metadata);applied.remove("allocations");applied.put("status","APPLIED");applyAllocation(c,refund,parcel,event,input,applied,returns);}
    @SuppressWarnings("unchecked") private void applyAllocation(String c,long refund,long parcel,long event,Map<String,Object> input,Map<String,Object> metadata,RefundReturnService returns){
        Set<Long> plans=new HashSet<>();db.tx().execute(tx->{Map<String,Object> locked=authorize(c,refund,parcel,true);if(metadata.containsKey("parcel_version"))require(n(metadata.get("parcel_version"))==n(locked.get("control_version")),"包裹实收已变化，请重新评估");Map<String,Object> e=db.one("SELECT * FROM wms_refund_parcel_receipt WHERE company_code=? AND parcel_id=? AND id=? FOR UPDATE",c,parcel,event);require("WAIT_ALLOCATION".equals(e.get("state")),"本次包裹回传已处理，请刷新");require(Boolean.TRUE.equals(input.get("confirmed")),"请确认本次实物数量与各退款归属");String decision=required(input,"decision",16),actor=required(input,"actor",64),reason=required(input,"reason",500),evidence=required(input,"evidence",1000);require(Arrays.asList("ALLOCATE","REJECT").contains(decision),"处理动作无效");
            if("ALLOCATE".equals(decision)){
                WmsProtocol.Receipt raw;try{raw=db.json.readValue(text(e.get("payload")),WmsProtocol.Receipt.class);}catch(Exception bad){throw new IllegalArgumentException("原包裹回传无法读取");}
                require(input.get("allocations") instanceof List,"请明确各行实际归属");List<Map<String,Object>> allocations=(List<Map<String,Object>>)input.get("allocations");require(!allocations.isEmpty()&&allocations.size()<=500,"分配明细无效或超过500行");
                long[] good=new long[raw.lines.size()],bad=new long[raw.lines.size()];Map<Long,WmsProtocol.Receipt> split=new TreeMap<>();Map<Long,Map<String,Object>> tasks=new TreeMap<>();
                for(Map<String,Object> a:allocations){require(a.containsKey("line_index")&&id(a.get("task_id"))>0,"必须明确原回传行和退回单归属");int index=Math.toIntExact(id(a.get("line_index")));require(index>=0&&index<raw.lines.size(),"原回传行无效");long task=id(a.get("task_id")),g=id(a.get("good_qty")),b=id(a.get("bad_qty"));require(g>=0&&b>=0&&g+b>0&&g+b<=100000000,"分配数量无效");good[index]+=g;bad[index]+=b;WmsProtocol.Line original=raw.lines.get(index);
                    Map<String,Object> warehouseDoc=db.one("SELECT * FROM wms_refund_parcel_document WHERE company_code=? AND id=?",c,e.get("document_id"));List<Map<String,Object>> scope;try{scope=db.json.readValue(text(warehouseDoc.get("payload")),List.class);}catch(Exception failure){throw new IllegalArgumentException("共同THK来源快照不可读");}require(scope.stream().anyMatch(row->id(row.get("task_id"))==task),"分配来源不属于原回传THK");if("CONFIRMED".equals(warehouseDoc.get("cancel_state")))require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_document WHERE company_code=? AND parcel_id=? AND cancel_state<>'CONFIRMED' AND generation>?",Long.class,c,parcel,warehouseDoc.get("generation"))==0,"请先截停后续共同THK，再确认旧单迟到实收");
                    Map<String,Object> t=tasks.computeIfAbsent(task,k->db.one("SELECT t.* FROM wms_refund_parcel_member m JOIN wms_refund_return t ON t.company_code=m.company_code AND t.id=m.task_id WHERE m.company_code=? AND m.parcel_id=? AND m.task_id=? FOR UPDATE",c,parcel,k));require(text(original.lineNo).isEmpty()||db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_member WHERE company_code=? AND parcel_id=? AND task_id=? AND id=?",Long.class,c,parcel,task,original.lineNo)==1,"明细行号不属于所选退款来源");require(text(t.get("sku_sn")).equals(original.sku),"分配商品与退回单SKU不一致；错货请核对，不能直接入账");require(Arrays.asList("ACCEPTED","CANCELED").contains(text(t.get("dispatch_state"))),"所选退回单尚未明确受理");
                    WmsProtocol.Receipt part=split.computeIfAbsent(task,k->{WmsProtocol.Receipt r=new WmsProtocol.Receipt();r.ticketSn=text(t.get("return_sn"));r.externalOrder=text(t.get("external_order"));r.warehouse=raw.warehouse;r.owner=raw.owner;r.messageId=raw.messageId;r.status="PARTFULFILLED";return r;});
                    WmsProtocol.Line line=new WmsProtocol.Line();line.sku=original.sku;line.owner=original.owner;line.batch=original.batch;line.good=Math.toIntExact(g);line.bad=Math.toIntExact(b);part.lines.add(line);
                }
                for(int i=0;i<raw.lines.size();i++)require(good[i]==raw.lines.get(i).good&&bad[i]==raw.lines.get(i).bad,"必须按原回传逐行、良次品完整分配；不得重复或遗漏数量");
                for(Map.Entry<Long,WmsProtocol.Receipt> part:split.entrySet()){Map<String,Object> t=tasks.get(part.getKey());require(id(t.get("accepted_quantity"))+quantity(part.getValue())<=id(t.get("quantity")),"分配后超过退回单剩余数量");part.getValue().complete=id(t.get("accepted_quantity"))+quantity(part.getValue())==id(t.get("quantity"));part.getValue().status=part.getValue().complete?"FULFILLED":"PARTFULFILLED";returns.acceptAssigned(c,t,part.getValue(),id(e.get("source_log_id")));plans.add(id(t.get("plan_id")));}
            }
            db.jdbc.update("UPDATE wms_refund_parcel_receipt SET state=?,allocation_json=?,allocation_metadata=?,auto_after=NULL,actor=?,reason=?,evidence=? WHERE company_code=? AND id=?","ALLOCATE".equals(decision)?"ALLOCATED":"REJECTED",db.encode(input.getOrDefault("allocations",Collections.emptyList())),db.encode(metadata),actor,reason,evidence,c,event);db.jdbc.update("UPDATE wms_refund_parcel SET control_version=control_version+1 WHERE company_code=? AND id=?",c,parcel);notifyPlans(c,parcel);Map<String,Object> p=parcel(c,parcel,false);long log=logs.start(c,id(p.get("connection_id")),null,text(p.get("parcel_sn")),"LOCAL","REFUND_PARCEL_REVIEW",db.encode(input));logs.finish(log,"SUCCESS","已记录合包回传核对结论","",0);logs.describe(log,"ALLOCATE".equals(decision)?"已明确本次商品归属；各退款按共同THK原实收消息幂等记账":"已拒绝本次合包回传入账；实物处置依据已留存");return null;
        });for(Long plan:plans)returns.postAssigned(c,plan);if(shared!=null)shared.syncTicket(c,parcel);
    }
}
